def finite_turn_required():
    # None preserves legacy standalone CLI's marker. A bound owner turn must
    # never inherit process launch flags from another viewer.
    return _finite_turn.get()

def unattended_turn():
    # `hermes -z`: nobody can answer a prompt, so the classic one-shot contract auto-approves
    # (legacy oneshot.py set HERMES_YOLO_MODE). `-q` stays single-query (approvals.single_query_mode).
    return _unattended_turn.get()

@contextmanager
def finite_turn_scope(finite, unattended=False):
    token = _finite_turn.set(finite)
    unattended_token = _unattended_turn.set(bool(finite and unattended))
    try:
        yield
    finally:
        _unattended_turn.reset(unattended_token)
        _finite_turn.reset(token)

def _yolo_active() -> bool:
    """CLI ``--yolo`` (process-scoped, frozen at import) or gateway ``/yolo``
    (session-scoped). Hardline / deny-rule floors run BEFORE this everywhere."""
    if _YOLO_MODE_FROZEN or is_current_session_yolo_enabled():
        return True
    from gateway.session_finite import unattended_turn
    return unattended_turn()

@dataclass(frozen=True)
class _Unattended:
    """One non-interactive context and the text every gate uses to explain it."""
    name: str       # "single_query" | "cron" | "unattended"
    cfg_key: str    # approvals.<cfg_key>: approve|deny
    clause: str     # "why nobody can approve" (lower-case sentence fragment)
    scope: str      # "in cron jobs" — completes "To allow ... {scope}"
    trust: str      # execute_code: "approve only if {trust}"

    def mode(self) -> str:
        # Looked up on the defining module at call time so tests patching the getters keep working.
        return getattr(approval_context, f"_get_{self.name}_approval_mode")()

    def block_message(self, subject: str, *, noun: str, advice: str) -> str:
        return (f"BLOCKED: {subject} but {self.clause}. {advice} To allow {noun} {self.scope}, set "
                f"approvals.{self.cfg_key}: approve in config.yaml.")

    @property
    def exec_tail(self) -> str:
        return (f"{self.clause[0].upper()}{self.clause[1:]}. Use normal tools "
                f"instead, or set approvals.{self.cfg_key}: approve only if {self.trust}.")

def _pending_findings(findings: list[tuple[str, str]], approved) -> tuple[list[str], str] | None:
    """``(pattern_keys, description)`` of *findings* still needing consent, or None.
    ``approved(key)`` is the session or permanent check."""
    pending = [(key, text) for key, text in findings if not approved(key)]
    if not pending:
        return None
    return [key for key, _ in pending], "; ".join(text for _, text in pending)

def _unapproved_findings(command: str, approved) -> tuple[list[str], str] | None:
    """:func:`_pending_findings` over :func:`_command_findings` of *command*."""
    return _pending_findings(_command_findings(command), approved)

def _approved_with_provenance(findings: list[tuple[str, str]], scopes: dict[str, str | None]) -> dict:
    """Approved result for a command whose *findings* (possibly none) an earlier answer covers.
    *scopes* are the :func:`_approval_scope` reads the approval check itself accepted; rereading the
    stores here could label a grant revoked since the check as a session answer."""
    if not findings:
        return _approved()
    return preapproved_result(findings, scopes.__getitem__)

def _unattended_deny(command: str, ctx: _Unattended) -> dict | None:
    """Deny-mode handling for one unattended context (cron / -q / webhook); None = allow."""
    if ctx.mode() != "deny":
        return None

    def block(subject: str) -> dict:
        return {"approved": False, "message": ctx.block_message(
            subject, noun="dangerous commands",
            advice="Find an alternative approach that avoids this command.")}

    pending = _unapproved_findings(command, _is_permanently_approved)
    if pending is not None:
        keys, description = pending
        result = block(f"Command flagged as dangerous ({description})")
        if ctx.name == "single_query":
            result.update(pattern_key=keys[0], description=description)
        return result
    return None

def check_dangerous_command(command: str, env_type: str,
                            approval_callback=None,
                            has_host_access: bool = False) -> dict:
    """Detect a dangerous command and handle approval (pattern layer only). ``has_host_access``:
    a Docker sandbox that bind-mounts host paths must not skip approval.
    Returns ``{"approved": True/False, "message": str or None, ...}``."""
    if _should_skip_container_guards(env_type, has_host_access=has_host_access):
        return _user_deny_block(command) or _approved()
    blocked = _floor_block(command)
    if blocked is not None:
        return blocked
    unread = hardline_scan_incomplete(command)
    if _yolo_active() or approval_context._get_approval_mode() == "off":
        return _scan_incomplete_block(_NO_REVIEWER_BYPASS) if unread else _approved()
    if unread:
        _approval_callback, is_cli, is_gateway, is_ask = _presence(approval_callback)
        if not (is_cli or is_gateway or is_ask):
            return _scan_incomplete_block(_NO_REVIEWER_PRESENT)
    elif _command_matches_permanent_allowlist(command):
        return _allowlisted(command)
    session_key = get_current_session_key()
    findings = _command_findings(command)
    scopes = {key: _approval_scope(session_key, key) for key, _ in findings}
    pending = _pending_findings(findings, lambda key: scopes[key] is not None)
    if pending is None:
        return _approved_with_provenance(findings, scopes)
    keys, description = pending
    return _run_approval_gate(
        pattern_key=keys[0], pattern_keys=keys, description=description, display_target=command,
        approval_callback=approval_callback,
        subject=f"Command flagged as dangerous ({description})", noun="dangerous commands",
        advice="Find an alternative approach that avoids this command.",
        autoapprove_log_prefix="AUTO-APPROVED dangerous command in non-interactive non-gateway context",
    )
